import secrets, hashlib

sessions = {}
STORED_HASH = hashlib.md5(b"s3cr3t").hexdigest()

def login(user_id, password):
    if hashlib.md5(password.encode()).hexdigest() == STORED_HASH:
        token = secrets.token_hex(16)
        sessions[token] = {"user_id": user_id, "active": True}
        return token
    return None

def get_user(token):
    s = sessions.get(token)
    return s["user_id"] if s and s["active"] else None

token = login("alice", "s3cr3t")
print("Token issued:", token is not None)
print("User:", get_user(token))
print("Bad token:", get_user("invalid"))
